<script setup>
import { onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { Search } from '@element-plus/icons-vue'
import { api, money, useRequestError } from '../api'
import PageHeading from '../components/PageHeading.vue'
const onError=useRequestError();const rows=ref([]);const query=ref('');const loading=ref(false);const dialog=ref(false);const saving=ref(false)
const form=ref({sku:'',name:'',category:'',unit:'件',price:'',cost:'',stock:0,reorder_level:0})
async function load(){loading.value=true;try{const q=query.value?`?q=${encodeURIComponent(query.value)}&page_size=100`:'?page_size=100';rows.value=(await api.products(q)).items}catch(e){onError(e)}finally{loading.value=false}}
function open(){form.value={sku:'',name:'',category:'',unit:'件',price:'',cost:'',stock:0,reorder_level:0};dialog.value=true}
async function submit(){if(!form.value.sku.trim()||!form.value.name.trim()){ElMessage.warning('商品编码和名称不能为空');return}saving.value=true;try{await api.createProduct({sku:form.value.sku,name:form.value.name,category:form.value.category,unit:form.value.unit,price_cents:Math.round(Number(form.value.price||0)*100),cost_cents:Math.round(Number(form.value.cost||0)*100),stock:Number(form.value.stock),reorder_level:Number(form.value.reorder_level)});ElMessage.success('商品已添加');dialog.value=false;await load()}catch(e){onError(e)}finally{saving.value=false}}
onMounted(load)
</script>
<template><div><PageHeading title="商品管理" subtitle="维护商品资料、售价和安全库存"><template #default><el-button type="primary" @click="open"><el-icon><Plus/></el-icon>新增商品</el-button></template></PageHeading><section class="surface module-surface"><div class="filter-bar"><el-input v-model="query" placeholder="搜索商品名称、编码或分类" :prefix-icon="Search" clearable @keyup.enter="load" @clear="load"/><el-button @click="load">搜索</el-button><span class="filter-count">{{ rows.length }} 件商品</span></div><div class="table-scroll"><el-table :data="rows" v-loading="loading" stripe style="width:100%" empty-text="暂无商品"><el-table-column prop="sku" label="商品编码" min-width="125"/><el-table-column prop="name" label="商品名称" min-width="210"/><el-table-column prop="category" label="分类" min-width="130"/><el-table-column prop="unit" label="单位" width="80"/><el-table-column label="销售价" width="135"><template #default="s">{{ money(s.row.price_cents) }}</template></el-table-column><el-table-column label="库存" width="100"><template #default="s"><strong :class="{'stock-low':s.row.stock<=s.row.reorder_level}">{{ s.row.stock }}</strong></template></el-table-column><el-table-column label="安全库存" width="110"><template #default="s">{{ s.row.reorder_level }}</template></el-table-column><el-table-column label="库存状态" width="120"><template #default="s"><el-tag :type="s.row.stock<=s.row.reorder_level?'danger':'success'" effect="light">{{ s.row.stock<=s.row.reorder_level?'库存预警':'库存充足' }}</el-tag></template></el-table-column></el-table></div></section><el-dialog v-model="dialog" title="新增商品" width="560px"><el-form label-position="top" class="form-grid"><el-form-item label="商品编码" required><el-input v-model="form.sku" placeholder="如 SP0007"/></el-form-item><el-form-item label="商品名称" required><el-input v-model="form.name"/></el-form-item><el-form-item label="商品分类"><el-input v-model="form.category"/></el-form-item><el-form-item label="单位"><el-input v-model="form.unit"/></el-form-item><el-form-item label="销售价（元）"><el-input-number v-model="form.price" :min="0" :precision="2" :step="1"/></el-form-item><el-form-item label="采购成本（元）"><el-input-number v-model="form.cost" :min="0" :precision="2" :step="1"/></el-form-item><el-form-item label="期初库存"><el-input-number v-model="form.stock" :min="0" :precision="0"/></el-form-item><el-form-item label="安全库存"><el-input-number v-model="form.reorder_level" :min="0" :precision="0"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="submit">保存商品</el-button></template></el-dialog></div></template>
